/**
 * EZYCORE BRIDGE - v1.3.0
 * Fallback discovery: DOM (#ezy-jsonld-bin) → localStorage cache → Blogger Feed API.
 * Blogger Feed tidak memanggil GAS — hanya JSON statis dari Blogger.
 * Firebase Auth: initialize + helper sign-in Google / email (via compat SDK).
 */
(function () {
    window.EzyApi = {
        url: '',
        role: 'Public',
        isReady: false,
        firebase: null
    };

    var PUBLIC_CONFIG_KEY = 'Ezycore_PublicConfig';

    function getPublicConfig() {
        try {
            var raw = localStorage.getItem(PUBLIC_CONFIG_KEY);
            return raw ? JSON.parse(raw) : {};
        } catch (e) {
            return {};
        }
    }

    function savePublicConfig(config) {
        config = config || {};
        try {
            localStorage.setItem(PUBLIC_CONFIG_KEY, JSON.stringify({
                siteKey: config.siteKey || '',
                webAppUrl: config.webAppUrl || '',
                firebaseApiKey: config.firebaseApiKey || '',
                projectId: config.projectId || ''
            }));
            if (config.siteKey) localStorage.setItem('Ezycore_SiteKey', config.siteKey);
        } catch (e) { }
    }

    // ---------- FIREBASE AUTH ----------

    // Inisialisasi Firebase App dari config discovery (tanpa memanggil GAS).
    function initFirebase(config) {
        config = config || {};
        var apiKey = config.firebaseApiKey || '';
        var projectId = config.projectId || '';
        if (!apiKey || !projectId) return false;
        if (typeof firebase === 'undefined') return false;

        try {
            if (!firebase.apps.length) {
                firebase.initializeApp({
                    apiKey: apiKey,
                    authDomain: projectId + '.firebaseapp.com',
                    projectId: projectId
                });
            }
            window.EzyApi.firebase = firebase;
            console.log('[Bridge] Firebase initialized:', projectId);
            return true;
        } catch (e) {
            console.warn('[Bridge] Firebase init skipped:', e.message);
            return false;
        }
    }

    // Normalisasi user object hasil sign-in Firebase menjadi shape seragam.
    function mapAuthUser(user) {
        if (!user) return null;
        var profile = (user.providerData && user.providerData[0]) || user;
        return {
            uid: user.uid || '',
            email: user.email || profile.email || '',
            displayName: user.displayName || profile.displayName || profile.name || '',
            photoURL: user.photoURL || profile.photoURL || profile.pictureUrl || '',
            emailVerified: !!user.emailVerified
        };
    }

    // Helper auth publik — dipakai Alpine store (ezycorescrewfast.xml) tanpa akses firebase langsung.
    function authReady() {
        if (!initFirebase(getPublicConfig())) {
            throw new Error('Firebase Auth tidak tersedia. Pastikan konfigurasi Firebase sudah disimpan.');
        }
        return window.EzyApi.firebase.auth();
    }

    window.EzyApi.auth = {
        // Google Sign-In (popup). Kembalikan Promise → user object.
        signInWithGoogle: function () {
            var auth = authReady();
            var provider = new firebase.auth.GoogleAuthProvider();
            return auth.signInWithPopup(provider)
                .then(function (result) { return mapAuthUser(result.user); });
        },

        signIn: function (email, password) {
            return authReady().signInWithEmailAndPassword(email, password)
                .then(function (result) { return mapAuthUser(result.user); });
        },

        signUp: function (email, password) {
            return authReady().createUserWithEmailAndPassword(email, password)
                .then(function (result) { return mapAuthUser(result.user); });
        },

        recover: function (email) {
            return authReady().sendPasswordResetEmail(email);
        },

        signOut: function () {
            return authReady().signOut();
        },

        getCurrentUser: function () {
            var auth = authReady();
            return mapAuthUser(auth.currentUser);
        },

        onAuthStateChanged: function (cb) {
            var auth = authReady();
            return auth.onAuthStateChanged(function (user) { cb(mapAuthUser(user)); });
        }
    };

    // Fallback 3: Remote Discovery via Blogger Feed API (TANPA panggilan GAS)
    function discoverViaBloggerFeed() {
        return fetch('/feeds/pages/default?alt=json')
            .then(function (res) { return res.json(); })
            .then(function (data) {
                var entries = (data.feed && data.feed.entry) || [];
                var configPage = entries.find(function (e) { return e.title && e.title.$t === 'EzyCore System Configuration'; });
                if (!configPage) return null;

                var content = configPage.content && configPage.content.$t ? configPage.content.$t : '';
                var match = content.match(/data-config="([^"]+)"/);
                if (!match || !match[1]) return null;

                var decoded = JSON.parse(atob(match[1]));
                return {
                    siteKey: decoded.siteKey || '',
                    webAppUrl: decoded.webappUrl || '',
                    firebaseApiKey: decoded.firebaseApiKey || '',
                    projectId: decoded.projectId || ''
                };
            })
            .catch(function () { return null; });
    }

    function finishDiscovery(config) {
        config = config || {};
        var siteKey = config.siteKey || '';
        var webAppUrl = config.webAppUrl || '';
        window.appsScriptUrl = webAppUrl;
        window.EzyApi.url = webAppUrl;
        window.EzyApi.isReady = !!webAppUrl;
        if (siteKey) localStorage.setItem('Ezycore_SiteKey', siteKey);
        initFirebase(config);

        window.dispatchEvent(new CustomEvent('ezy-api-ready', { detail: window.EzyApi }));
    }

    function initPublicDiscovery() {
        var bin = document.getElementById('ezy-jsonld-bin');
        var cached = getPublicConfig();
        var config = {
            siteKey: cached.siteKey || localStorage.getItem('Ezycore_SiteKey') || '',
            webAppUrl: window.appsScriptUrl || cached.webAppUrl || '',
            firebaseApiKey: cached.firebaseApiKey || '',
            projectId: cached.projectId || ''
        };

        // 1. Prioritas tertinggi: elemen #ezy-jsonld-bin di DOM (SSR)
        if (bin && bin.textContent.trim()) {
            try {
                var metadata = JSON.parse(atob(bin.textContent.trim()));
                config.siteKey = metadata.siteKey || config.siteKey;
                config.webAppUrl = metadata.webAppUrl || metadata.webappUrl || config.webAppUrl;
                config.firebaseApiKey = metadata.firebaseApiKey || config.firebaseApiKey;
                config.projectId = metadata.projectId || config.projectId;

                savePublicConfig(config);
                console.log('[Bridge] Discovery Success (DOM):', config.siteKey);
                finishDiscovery(config);
                return;
            } catch (e) {
                console.warn('[Bridge] Metadata extraction failed from Bin');
            }
        }

        // 2. Cek localStorage cache — 0 network call, 0 GAS
        if (config.webAppUrl) {
            console.log('[Bridge] Discovery Success (Cache):', config.siteKey);
            savePublicConfig(config);
            finishDiscovery(config);
            return;
        }

        // 3. Fallback: Blogger Feed API (hanya bila cache kosong)
        console.log('[Bridge] Discovery: Mencoba Blogger Feed API...');
        discoverViaBloggerFeed().then(function (result) {
            if (result && result.webAppUrl) {
                console.log('[Bridge] Discovery Success (Feed):', result.siteKey);
                savePublicConfig(result);
                finishDiscovery(result);
            } else {
                console.error('[Bridge] Discovery Gagal: tidak ada config yang ditemukan.');
                finishDiscovery({});
            }
        });
    }

    window.sendDataToGoogle = function (action, data, callback, errorHandler) {
        if (!window.EzyApi.isReady) {
            setTimeout(() => window.sendDataToGoogle(action, data, callback, errorHandler), 300);
            return;
        }

        const postActions = ['placeOrder', 'submitContact'];

        const payload = {
            action,
            siteKey: localStorage.getItem('Ezycore_SiteKey'),
            ...data
        };

        if (postActions.includes(action)) {
            fetch(window.EzyApi.url, {
                method: 'POST',
                headers: { 'Content-Type': 'text/plain' },
                body: JSON.stringify(payload)
            })
                .then(res => res.json())
                .then(callback)
                .catch(err => errorHandler?.(err));
        } else {
            const cbName = 'ezy_pub_cb_' + Date.now();
            window[cbName] = (res) => { delete window[cbName]; callback?.(res); };
            const query = new URLSearchParams({ ...payload, callback: cbName }).toString();
            const script = document.createElement('script');
            script.src = `${window.EzyApi.url}${window.EzyApi.url.includes('?') ? '&' : '?'}${query}`;
            document.head.appendChild(script);
        }
    };

    window.AdminAPI = {
        checkConnection: async () => {
            return new Promise(resolve => {
                window.sendDataToGoogle('ping', {},
                    (res) => resolve({ connected: res.status === 'success', error: null }),
                    (err) => resolve({ connected: false, error: err.message }));
            });
        }
    };

    initPublicDiscovery();
})();
